// Percent-encoding helpers that mirror Python's urllib.parse behavior:
//   quote()       - urllib.parse.quote       (UTF-8 bytes, uppercase hex)
//   quotePlus()   - urllib.parse.quote_plus  (space rendered as '+')
//   unquote()     - urllib.parse.unquote     (invalid escapes kept, bad
//                                            UTF-8 replaced with U+FFFD)
//   unquotePlus() - urllib.parse.unquote_plus ('+' decoded to space first)

const ALWAYS_SAFE =
  'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_.-~';

const encoder = new TextEncoder();
const decoder = new TextDecoder('utf-8', { fatal: false });

function toHex(byte) {
  return '%' + byte.toString(16).toUpperCase().padStart(2, '0');
}

export function quote(str, safe = '/') {
  const safeSet = new Set(ALWAYS_SAFE + safe);
  let out = '';
  for (const byte of encoder.encode(str)) {
    const ch = String.fromCharCode(byte);
    out += safeSet.has(ch) ? ch : toHex(byte);
  }
  return out;
}

export function quotePlus(str, safe = '') {
  const safeSet = new Set(ALWAYS_SAFE + safe);
  let out = '';
  for (const byte of encoder.encode(str)) {
    const ch = String.fromCharCode(byte);
    if (byte === 0x20) out += '+';
    else out += safeSet.has(ch) ? ch : toHex(byte);
  }
  return out;
}

const HEX_DIGIT = /[0-9A-Fa-f]/;

export function unquote(str) {
  if (!str.includes('%')) return str;
  const bytes = [];
  let literal = '';
  const flush = () => {
    if (literal !== '') {
      for (const byte of encoder.encode(literal)) bytes.push(byte);
      literal = '';
    }
  };
  let i = 0;
  while (i < str.length) {
    if (
      str[i] === '%' &&
      i + 2 < str.length + 1 &&
      HEX_DIGIT.test(str[i + 1] ?? '') &&
      HEX_DIGIT.test(str[i + 2] ?? '')
    ) {
      flush();
      bytes.push(parseInt(str.slice(i + 1, i + 3), 16));
      i += 3;
    } else {
      literal += str[i];
      i += 1;
    }
  }
  flush();
  return decoder.decode(new Uint8Array(bytes));
}

export function unquotePlus(str) {
  return unquote(str.replace(/\+/g, ' '));
}

