// URL splitting and joining that mirrors Python's urllib.parse.urlsplit /
// urlunsplit, including the netloc ('//authority') handling and furl's
// default-port elision.

// Schemes for which urlunsplit emits '//' even with an empty netloc
// (Python's urllib.parse.uses_netloc).
export const USES_NETLOC = new Set([
  '', 'ftp', 'http', 'gopher', 'nntp', 'telnet', 'wais', 'imap', 'file',
  'mms', 'https', 'shttp', 'snews', 'prospero', 'rtsp', 'rtsps', 'rtspu',
  'rsync', 'svn', 'svn+ssh', 'sip', 'sips',
]);

// Default ports elided by furl when rendering the authority.
export const DEFAULT_PORTS = {
  ftp: 21, ssh: 22, sftp: 22, telnet: 23, tftp: 69, gopher: 70, http: 80,
  ws: 80, nntp: 119, imap: 143, irc: 194, wais: 210, ldap: 389,
  https: 443, wss: 443, rtsp: 554, rtsps: 322, snews: 563, nntps: 563,
  ldaps: 636, rsync: 873, mms: 1755, dict: 2628, svn: 3690, git: 9418,
  sip: 5060, sips: 5061,
};

const SCHEME_RE = /^[A-Za-z][A-Za-z0-9+.-]*$/;

export function urlsplit(url) {
  // urlsplit strips tab/CR/LF anywhere and leading C0-control/space chars.
  url = url.replace(/[\t\r\n]/g, '').replace(/^[\x00-\x20]+/, '');

  let scheme = '';
  let netloc = '';
  let query = '';
  let fragment = '';

  let i = url.indexOf('#');
  if (i !== -1) {
    fragment = url.slice(i + 1);
    url = url.slice(0, i);
  }
  i = url.indexOf('?');
  if (i !== -1) {
    query = url.slice(i + 1);
    url = url.slice(0, i);
  }

  const colon = url.indexOf(':');
  const slash = url.indexOf('/');
  if (colon > 0 && (slash === -1 || colon < slash)) {
    const candidate = url.slice(0, colon);
    if (SCHEME_RE.test(candidate)) {
      scheme = candidate.toLowerCase();
      url = url.slice(colon + 1);
    }
  }

  let path;
  if (url.startsWith('//')) {
    const rest = url.slice(2);
    const cut = rest.indexOf('/');
    if (cut === -1) {
      netloc = rest;
      path = '';
    } else {
      netloc = rest.slice(0, cut);
      path = rest.slice(cut);
    }
  } else {
    path = url;
  }

  return { scheme, netloc, path, query, fragment };
}

// Splits an authority into userinfo/host/port. The port must be a valid
// number in 0..65535; anything else raises like furl does.
export function splitNetloc(netloc) {
  let userinfo = '';
  let hostport = netloc;
  const at = netloc.lastIndexOf('@');
  if (at !== -1) {
    userinfo = netloc.slice(0, at);
    hostport = netloc.slice(at + 1);
  }

  let host = hostport;
  let port = null;
  if (hostport.startsWith('[')) {
    const close = hostport.indexOf(']');
    if (close !== -1) {
      host = hostport.slice(0, close + 1);
      const rest = hostport.slice(close + 1);
      if (rest.startsWith(':')) port = parsePort(rest.slice(1));
    }
  } else {
    const colon = hostport.lastIndexOf(':');
    if (colon !== -1) {
      host = hostport.slice(0, colon);
      port = parsePort(hostport.slice(colon + 1));
    }
  }

  return { userinfo, host: host.toLowerCase(), port };
}

function parsePort(text) {
  if (!/^[0-9]+$/.test(text)) throw new Error(`Invalid port '${text}'.`);
  const port = parseInt(text, 10);
  if (port > 65535) throw new Error(`Invalid port '${text}'.`);
  return port;
}

export function joinNetloc({ userinfo, host, port }, scheme) {
  let netloc = '';
  if (userinfo !== '') netloc += userinfo + '@';
  netloc += host;
  if (port !== null && port !== DEFAULT_PORTS[scheme]) netloc += ':' + port;
  return netloc;
}

export function urlunsplit({ scheme, netloc, path, query, fragment }) {
  let url = path;
  if (netloc || (scheme && USES_NETLOC.has(scheme) && !url.startsWith('//'))) {
    if (url && !url.startsWith('/')) url = '/' + url;
    url = '//' + (netloc || '') + url;
  }
  if (scheme) url = scheme + ':' + url;
  if (query) url = url + '?' + query;
  if (fragment) url = url + '#' + fragment;
  return url;
}

