// Minimal reimplementation of the furl object's observable behavior:
// parsing a URL into scheme/netloc/path/query/fragment and rendering
// it back with the same normalization furl applies.

import { Path } from './path.mjs';
import { Query } from './query.mjs';
import { Fragment } from './fragment.mjs';
import { urlsplit, urlunsplit, splitNetloc, joinNetloc } from './urlsplit.mjs';

export class Furl {
  constructor(url) {
    const parts = urlsplit(url);
    this.scheme = parts.scheme;
    const { userinfo, host, port } = splitNetloc(parts.netloc);
    this.userinfo = userinfo;
    this.host = host;
    this.port = port;
    this.path = new Path(parts.path);
    this.query = new Query(parts.query);
    this.fragment = new Fragment(parts.fragment);
  }

  get url() {
    return urlunsplit({
      scheme: this.scheme,
      netloc: joinNetloc(this, this.scheme),
      path: this.path.render(),
      query: this.query.toString(),
      fragment: this.fragment.toString(),
    });
  }
}

export function furl(url) {
  return new Furl(url);
}

