const OPTIONS = ['a', 'b', 'c', 'd'];
const ALL_OPTIONS = [...OPTIONS, 'help'];

const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

function usageLine(prog) {
  return `usage: ${prog} [-h] --a A --b B --c C --d D`;
}

function printHelp(prog) {
  process.stdout.write(
    usageLine(prog) +
      '\n\noptions:\n' +
      '  -h, --help  show this help message and exit\n' +
      '  --a A\n  --b B\n  --c C\n  --d D\n'
  );
}

function fail(prog, message) {
  process.stderr.write(usageLine(prog) + '\n' + `${prog}: error: ${message}\n`);
  process.exit(2);
}

function looksLikeOption(token) {
  return (
    token.length > 1 && token.startsWith('-') && !NEGATIVE_NUMBER.test(token)
  );
}

function matchOption(name) {
  if (ALL_OPTIONS.includes(name)) return name;
  const matches = ALL_OPTIONS.filter((o) => o.startsWith(name));
  return matches.length === 1 ? matches[0] : null;
}

export function parseArgs(argv, scriptPath) {
  const prog = basename(scriptPath || 'test12.mjs');
  const values = {};
  const extras = [];
  let onlyPositional = false;

