    const token = argv[i];

    if (onlyPositional) {
      extras.push(token);
      continue;
    }
    if (token === '--') {
      onlyPositional = true;
      continue;
    }

    if (token.startsWith('--')) {
      const eq = token.indexOf('=');
      const name = token.slice(2, eq === -1 ? undefined : eq);
      const inlineValue = eq === -1 ? null : token.slice(eq + 1);
      const option = matchOption(name);

      if (option === null) {
        extras.push(token);
        continue;
