      if (option === 'help') {
        printHelp(prog);
        process.exit(0);
      }
      if (inlineValue !== null) {
        values[option] = inlineValue;
        continue;
      }
      const next = argv[i + 1];
      if (next === undefined || looksLikeOption(next)) {
        fail(prog, `argument --${option}: expected one argument`);
      }
      values[option] = next;
      i++;
      continue;
    }

    if (token.startsWith('-') && token.length > 1 && !NEGATIVE_NUMBER.test(token)) {
      if (token === '-h') {
        printHelp(prog);
        process.exit(0);
      }
      extras.push(token);
      continue;
    }

    extras.push(token);
  }

  const missing = OPTIONS.filter((o) => !(o in values));
  if (missing.length > 0) {
    fail(
      prog,
      'the following arguments are required: ' +
        missing.map((o) => '--' + o).join(', ')
    );
  }
  if (extras.length > 0) {
    fail(prog, 'unrecognized arguments: ' + extras.join(' '));
